let LANG = "en";

function t(key, values = {}) {
  const table = I18N[LANG] || I18N.en;
  let text = table[key] ?? I18N.en[key] ?? key;
  for (const [name, value] of Object.entries(values)) {
    text = text.split(`{${name}}`).join(String(value));
  }
  return text;
}

function toggleLanguage() {
  LANG = LANG === "en" ? "zh" : "en";
  return LANG;
}
